package main

import (
	"bytes"
	"errors"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"strings"
)

// rootType is the type whose comparison and hash the generator writes.
const rootType = "Style"

// outName is the generated file, which the generator leaves out of the
// package it type-checks.
const outName = "equal_gen.go"

var (
	errNoType      = errors.New("type not found in the package")
	errUnreadable  = errors.New("field of a type the generator cannot read")
	errInvalidType = errors.New("field of a type that does not type-check")
)

func main() {
	dir := flag.String("dir", ".", "directory of the css package")
	out := flag.String("out", outName, "Go file to write")
	flag.Parse()
	code, err := generate(*dir)
	if err == nil {
		err = os.WriteFile(filepath.Clean(*out), code, 0o600)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "gen-style-equal:", err)
		os.Exit(1)
	}
}

// generate type-checks the package in dir, its generated file and tests
// left out, and returns the source of the comparison and hash functions of
// [rootType] and of every struct type of the package it holds.
func generate(dir string) ([]byte, error) {
	pkg, err := load(dir)
	if err != nil {
		return nil, err
	}
	obj, ok := pkg.Scope().Lookup(rootType).(*types.TypeName)
	if !ok {
		return nil, fmt.Errorf("%s: %w", rootType, errNoType)
	}
	g := &gen{pkg: pkg, seen: map[*types.Named]bool{}}
	root, ok := obj.Type().(*types.Named)
	if !ok {
		return nil, fmt.Errorf("%s is not a named type: %w", rootType, errUnreadable)
	}
	g.queue = append(g.queue, root)
	g.seen[root] = true
	var body bytes.Buffer
	for len(g.queue) > 0 {
		n := g.queue[0]
		g.queue = g.queue[1:]
		if err := g.writeType(&body, n); err != nil {
			return nil, err
		}
	}
	var buf bytes.Buffer
	buf.WriteString("// Code generated by gen-style-equal; DO NOT EDIT.\n\n")
	fmt.Fprintf(&buf, "package %s\n\n", pkg.Name())
	buf.WriteString("import \"math\"\n\n")
	buf.Write(body.Bytes())
	return format.Source(buf.Bytes())
}

// load parses and type-checks the non-test files of dir but the generated
// one. The package refers to the generated functions, so errors that name
// them are expected; the types of the struct fields stay resolved, and a
// field whose type does not is refused when written.
func load(dir string) (*types.Package, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	var files []*ast.File
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") || name == outName {
			continue
		}
		f, err := parser.ParseFile(fset, filepath.Join(dir, name), nil, parser.SkipObjectResolution)
		if err != nil {
			return nil, err
		}
		files = append(files, f)
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("%s: no Go files", dir)
	}
	conf := types.Config{
		Importer: importer.ForCompiler(fset, "source", nil),
		Error:    func(error) {},
	}
	pkg, _ := conf.Check(files[0].Name.Name, fset, files, nil) //nolint:errcheck // errors about the generated functions are expected; an unresolved field type is refused in writeType
	return pkg, nil
}

// gen writes the functions of the struct types it meets, each once.
type gen struct {
	pkg   *types.Package
	seen  map[*types.Named]bool
	queue []*types.Named
	// depth numbers the loop variables of nested arrays and slices.
	depth int
}

// writeType writes the comparison and the hash of the struct type n.
func (g *gen) writeType(w *bytes.Buffer, n *types.Named) error {
	st, ok := n.Underlying().(*types.Struct)
	if !ok {
		return fmt.Errorf("%s: %w", n.Obj().Name(), errUnreadable)
	}
	name := n.Obj().Name()
	var eq, hs []string
	for f := range st.Fields() {
		a, b, x := "a."+f.Name(), "b."+f.Name(), "x."+f.Name()
		g.depth = 0
		e, err := g.equal(f.Type(), a, b)
		if err != nil {
			return fmt.Errorf("%s.%s: %w", name, f.Name(), err)
		}
		g.depth = 0
		h, err := g.hash(f.Type(), x)
		if err != nil {
			return fmt.Errorf("%s.%s: %w", name, f.Name(), err)
		}
		eq = append(eq, e...)
		hs = append(hs, h...)
	}
	fmt.Fprintf(w, "// equal%s reports whether a and b hold equal values, field by field.\n", name)
	fmt.Fprintf(w, "func equal%s(a, b *%s) bool {\n", name, name)
	for _, s := range eq {
		w.WriteString(s + "\n")
	}
	w.WriteString("return true\n}\n\n")
	fmt.Fprintf(w, "// hash%s folds every field of x into h.\n", name)
	fmt.Fprintf(w, "func hash%s(h uint64, x *%s) uint64 {\n", name, name)
	for _, s := range hs {
		w.WriteString(s + "\n")
	}
	w.WriteString("return h\n}\n\n")
	return nil
}

// structOf returns the struct type of the package t names, queuing its
// functions, or nil when t is not one.
func (g *gen) structOf(t types.Type) (*types.Named, error) {
	n, ok := t.(*types.Named)
	if !ok {
		if _, anon := t.Underlying().(*types.Struct); anon {
			return nil, fmt.Errorf("unnamed struct: %w", errUnreadable)
		}
		return nil, nil
	}
	if _, isStruct := n.Underlying().(*types.Struct); !isStruct {
		return nil, nil
	}
	if n.Obj().Pkg() != g.pkg {
		return nil, fmt.Errorf("struct %s of another package: %w", n, errUnreadable)
	}
	if !g.seen[n] {
		g.seen[n] = true
		g.queue = append(g.queue, n)
	}
	return n, nil
}

// loopVar returns a fresh loop variable.
func (g *gen) loopVar() string {
	g.depth++
	return fmt.Sprintf("i%d", g.depth)
}

// plain reports a type whose values Go's == compares as the generated
// comparison does: no float, complex, struct, slice, pointer or other
// reference kind among its elements.
func plain(t types.Type) bool {
	switch u := t.Underlying().(type) {
	case *types.Basic:
		return u.Info()&(types.IsFloat|types.IsComplex) == 0 && u.Kind() != types.UnsafePointer
	case *types.Array:
		return plain(u.Elem())
	}
	return false
}

// equal returns the statements that return false when the values a and b
// of type t differ.
func (g *gen) equal(t types.Type, a, b string) ([]string, error) {
	if n, err := g.structOf(t); err != nil || n != nil {
		if err != nil {
			return nil, err
		}
		return []string{fmt.Sprintf("if !equal%s(&%s, &%s) {\nreturn false\n}", n.Obj().Name(), a, b)}, nil
	}
	if plain(t) {
		return []string{fmt.Sprintf("if %s != %s {\nreturn false\n}", a, b)}, nil
	}
	switch u := t.Underlying().(type) {
	case *types.Basic:
		switch {
		case u.Kind() == types.Invalid:
			return nil, errInvalidType
		case u.Info()&types.IsFloat != 0:
			return []string{fmt.Sprintf("if %s != %s {\nreturn false\n}", floatBits(t, u, a), floatBits(t, u, b))}, nil
		case u.Info()&types.IsComplex != 0:
			return []string{fmt.Sprintf("if math.Float64bits(real(%[1]s)) != math.Float64bits(real(%[2]s)) || math.Float64bits(imag(%[1]s)) != math.Float64bits(imag(%[2]s)) {\nreturn false\n}", a, b)}, nil
		case u.Kind() == types.UnsafePointer:
			return []string{fmt.Sprintf("if %s != nil || %s != nil {\nreturn false\n}", a, b)}, nil
		}
	case *types.Array:
		i := g.loopVar()
		inner, err := g.equal(u.Elem(), a+"["+i+"]", b+"["+i+"]")
		if err != nil {
			return nil, err
		}
		return []string{fmt.Sprintf("for %s := range %s {\n%s\n}", i, a, strings.Join(inner, "\n"))}, nil
	case *types.Slice:
		i := g.loopVar()
		inner, err := g.equal(u.Elem(), a+"["+i+"]", b+"["+i+"]")
		if err != nil {
			return nil, err
		}
		// Two slices of one length over one array hold the same elements:
		// a style mostly holds the slices of the style it inherits from.
		return []string{
			fmt.Sprintf("if (%[1]s == nil) != (%[2]s == nil) || len(%[1]s) != len(%[2]s) {\nreturn false\n}", a, b),
			fmt.Sprintf("if len(%[2]s) > 0 && &%[2]s[0] != &%[3]s[0] {\nfor %[1]s := range %[2]s {\n%[4]s\n}\n}", i, a, b, strings.Join(inner, "\n")),
		}, nil
	case *types.Pointer:
		return []string{fmt.Sprintf("if %s != %s {\nreturn false\n}", a, b)}, nil
	case *types.Map, *types.Signature, *types.Chan, *types.Interface:
		return []string{fmt.Sprintf("if %s != nil || %s != nil {\nreturn false\n}", a, b)}, nil
	}
	return nil, fmt.Errorf("%s: %w", t, errUnreadable)
}

// hash returns the statements that fold the value x of type t into h.
func (g *gen) hash(t types.Type, x string) ([]string, error) {
	if n, err := g.structOf(t); err != nil || n != nil {
		if err != nil {
			return nil, err
		}
		return []string{fmt.Sprintf("h = hash%s(h, &%s)", n.Obj().Name(), x)}, nil
	}
	switch u := t.Underlying().(type) {
	case *types.Basic:
		info := u.Info()
		switch {
		case u.Kind() == types.Invalid:
			return nil, errInvalidType
		case info&types.IsBoolean != 0:
			return []string{fmt.Sprintf("h = mixBool(h, %s)", x)}, nil
		case info&types.IsString != 0:
			return []string{fmt.Sprintf("h = mixString(h, %s)", convert(t, "string", x))}, nil
		case info&types.IsFloat != 0:
			return []string{fmt.Sprintf("h = mix(h, %s)", floatBits(t, u, x))}, nil
		case info&types.IsComplex != 0:
			return []string{fmt.Sprintf("h = mix(h, math.Float64bits(real(%[1]s)))\nh = mix(h, math.Float64bits(imag(%[1]s)))", x)}, nil
		case u.Kind() == types.UnsafePointer:
			return []string{fmt.Sprintf("h = mixBool(h, %s != nil)", x)}, nil
		case u.Kind() == types.Uint64 && t == u:
			return []string{fmt.Sprintf("h = mix(h, %s)", x)}, nil
		case info&types.IsInteger != 0:
			return []string{fmt.Sprintf("h = mix(h, uint64(%s))", x)}, nil
		}
	case *types.Array:
		i := g.loopVar()
		inner, err := g.hash(u.Elem(), x+"["+i+"]")
		if err != nil {
			return nil, err
		}
		return []string{fmt.Sprintf("for %s := range %s {\n%s\n}", i, x, strings.Join(inner, "\n"))}, nil
	case *types.Slice:
		i := g.loopVar()
		inner, err := g.hash(u.Elem(), x+"["+i+"]")
		if err != nil {
			return nil, err
		}
		return []string{
			fmt.Sprintf("h = mixBool(h, %s == nil)\nh = mix(h, uint64(len(%s)))", x, x),
			fmt.Sprintf("for %s := range %s {\n%s\n}", i, x, strings.Join(inner, "\n")),
		}, nil
	case *types.Pointer, *types.Map, *types.Signature, *types.Chan, *types.Interface:
		// Equal pointers hold one address; the hash folds whether there
		// is one, never the address, so it does not vary between runs.
		return []string{fmt.Sprintf("h = mixBool(h, %s != nil)", x)}, nil
	}
	return nil, fmt.Errorf("%s: %w", t, errUnreadable)
}

// floatBits returns the expression of the bits of the float x of type t,
// whose underlying type is u.
func floatBits(t types.Type, u *types.Basic, x string) string {
	if u.Kind() == types.Float32 {
		return fmt.Sprintf("uint64(math.Float32bits(%s))", convert(t, "float32", x))
	}
	return fmt.Sprintf("math.Float64bits(%s)", convert(t, "float64", x))
}

// convert returns x converted to the basic type to when its type t is a
// named one, x itself otherwise.
func convert(t types.Type, to, x string) string {
	if _, named := t.(*types.Named); named {
		return to + "(" + x + ")"
	}
	return x
}
